#include <iostream>
#include <vector>
#algorithm
int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    int sum = 0;
    auto add_to_sum = [&sum](int value) { sum += value; };
    for (int num : numbers) {
        add_to_sum(num);
    }
    std::cout << "Sum: " << sum << std::endl;
    return 0;
}
